import { useSyncExternalStore } from 'react'
import type { Howl as HowlT } from 'howler'

/** Sound effects in public/sfx (generated by scripts/gen-sfx.mjs; original, CC0). */
export type Sfx = 'chip' | 'deal' | 'flip' | 'spin' | 'ball' | 'reel' | 'win' | 'lose' | 'boom' | 'tick'

export const MUTE_KEY = 'ict-casino:muted'
/** Long "ambience" sounds that only accompany animations; skipped under prefers-reduced-motion. */
const MOTION_ONLY: ReadonlySet<Sfx> = new Set(['spin', 'deal'])
const MIN_GAP_MS = 45 // collapse bursts (e.g. 18 cards dealt at once)

interface State { muted: boolean; unlocked: boolean; explicit: boolean }

const read = (): State => {
  let stored: string | null = null
  try { stored = localStorage.getItem(MUTE_KEY) } catch { /* private mode */ }
  // No saved choice: stay silent until the first interaction, then sounds turn on.
  return { muted: stored === null ? true : stored === '1', unlocked: false, explicit: stored !== null }
}

let state: State = typeof window === 'undefined' ? { muted: true, unlocked: false, explicit: false } : read()
const listeners = new Set<() => void>()
const emit = () => listeners.forEach((l) => l())
const set = (patch: Partial<State>) => { state = { ...state, ...patch }; emit() }

let howler: Promise<typeof import('howler')> | null = null
const howls = new Map<Sfx, HowlT>()
const lastPlayed = new Map<Sfx, number>()

/** Lazy-load Howler and the file only when a sound is first needed. */
async function getHowl(name: Sfx): Promise<HowlT> {
  howler ??= import('howler')
  const { Howl } = await howler
  let h = howls.get(name)
  if (!h) {
    const base = `${import.meta.env.BASE_URL}sfx/${name}`
    h = new Howl({ src: [`${base}.ogg`, `${base}.mp3`], volume: name === 'spin' ? 0.5 : 0.7 })
    howls.set(name, h)
  }
  return h
}

const reducedMotion = () => typeof window !== 'undefined' && !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches

/** Play a sound. Silently does nothing when muted, before the first user interaction, or for motion-only sounds under reduced motion. */
export function play(name: Sfx, opts: { rate?: number; volume?: number } = {}): void {
  if (state.muted || !state.unlocked) return
  if (MOTION_ONLY.has(name) && reducedMotion()) return
  const now = performance.now()
  if (now - (lastPlayed.get(name) ?? -1e9) < MIN_GAP_MS) return
  lastPlayed.set(name, now)
  void getHowl(name).then((h) => {
    if (state.muted) return
    const id = h.play()
    if (opts.rate) h.rate(opts.rate, id)
    if (opts.volume !== undefined) h.volume(opts.volume, id)
  }).catch(() => { /* audio unavailable */ })
}

/** Stop a (long) sound, e.g. the roulette spin when the ball lands. */
export function stop(name: Sfx): void { howls.get(name)?.stop() }

export function setMuted(muted: boolean): void {
  try { localStorage.setItem(MUTE_KEY, muted ? '1' : '0') } catch { /* ignore */ }
  if (muted) howls.forEach((h) => h.stop())
  set({ muted, explicit: true, unlocked: true })
}

/** Call once at startup: unlocks audio on the first pointer/key interaction (autoplay policy). */
export function installSoundUnlock(): () => void {
  const unlock = () => {
    if (state.unlocked) return
    set({ unlocked: true, muted: state.explicit ? state.muted : false })
  }
  // Delegated UI ticks: any button plays its data-sfx (default "tick"); data-sfx="none" opts out.
  const onClick = (e: MouseEvent) => {
    const el = (e.target as HTMLElement | null)?.closest?.('button')
    if (!el || (el as HTMLButtonElement).disabled) return
    const sfx = el.dataset.sfx
    if (sfx !== 'none') play((sfx as Sfx) || 'tick')
  }
  window.addEventListener('pointerdown', unlock, { capture: true })
  window.addEventListener('keydown', unlock, { capture: true })
  window.addEventListener('click', onClick)
  return () => {
    window.removeEventListener('pointerdown', unlock, { capture: true })
    window.removeEventListener('keydown', unlock, { capture: true })
    window.removeEventListener('click', onClick)
  }
}

const subscribe = (cb: () => void) => { listeners.add(cb); return () => { listeners.delete(cb) } }
const snapshot = () => state

/** Mute state + controls for React. */
export function useSound() {
  const s = useSyncExternalStore(subscribe, snapshot, snapshot)
  return { muted: s.muted, unlocked: s.unlocked, setMuted, toggleMute: () => setMuted(!s.muted), play, stop }
}

/** Test helper. */
export function __resetSound(next?: Partial<State>) { state = { ...read(), ...next }; howls.clear(); lastPlayed.clear(); emit() }

/** Handle for a looping sound whose rate/volume can be driven over time (e.g. a slowing roulette wheel). */
export interface LoopHandle { update(rate: number, volume: number): void; fadeOut(ms: number): void; stop(): void }
const NOOP_LOOP: LoopHandle = { update() {}, fadeOut() {}, stop() {} }

/** Start `name` looping. Same gating as play(); returns a no-op handle when it can't play. */
export function playLoop(name: Sfx, volume = 1): LoopHandle {
  if (state.muted || !state.unlocked) return NOOP_LOOP
  if (MOTION_ONLY.has(name) && reducedMotion()) return NOOP_LOOP
  let h: HowlT | null = null, id: number | null = null, dead = false
  let rate = 1, vol = volume
  void getHowl(name).then((howl) => {
    if (dead || state.muted) return
    h = howl; id = howl.play(); howl.loop(true, id); howl.rate(rate, id); howl.volume(vol, id)
  }).catch(() => { /* audio unavailable */ })
  return {
    update(r, v) { rate = r; vol = v; if (h && id !== null && !dead) { h.rate(r, id); h.volume(v, id) } },
    fadeOut(ms) { if (h && id !== null && !dead) { h.fade(h.volume(id) as number, 0, ms, id); const hh = h, ii = id; setTimeout(() => hh.stop(ii), ms + 20) } dead = true },
    stop() { dead = true; if (h && id !== null) h.stop(id) },
  }
}
